#!/usr/bin/env bash
set -euo pipefail

cd "$(dirname "$0")/.."
unset GOROOT

COMPOSE_FILE="deploy/standalone/docker-compose.yml"
PROJECT_NAME="${MOCHAT_STACK_PROJECT:-mochat-go-schema-migrate-check}"
MYSQL_PORT="${MOCHAT_MYSQL_PORT:-13331}"
WORK_DIR="$(mktemp -d "${TMPDIR:-/tmp}/mochat-go-schema-migrate.XXXXXX")"
MIGRATE_BIN="$WORK_DIR/mochat-migrate"

compose() {
  MOCHAT_MYSQL_PORT="$MYSQL_PORT" docker compose -p "$PROJECT_NAME" -f "$COMPOSE_FILE" "$@"
}

cleanup() {
  rm -rf "$WORK_DIR"
  if [ "${KEEP_STACK:-0}" != "1" ]; then
    compose down -v --remove-orphans >/dev/null 2>&1 || true
  fi
}
trap cleanup EXIT INT TERM

assert_port_free() {
  local port="$1"
  if lsof -nP -iTCP:"$port" -sTCP:LISTEN >/dev/null 2>&1; then
    echo "port $port is already in use" >&2
    exit 1
  fi
}

wait_service_healthy() {
  local service="$1"
  local deadline=$((SECONDS + ${MOCHAT_SERVICE_HEALTH_TIMEOUT_SECONDS:-360}))
  while [ "$SECONDS" -lt "$deadline" ]; do
    local status
    status="$(compose ps --format json "$service" 2>/dev/null | python3 -c 'import json,sys; data=sys.stdin.read().strip(); print(json.loads(data).get("Health", "")) if data else print("")' 2>/dev/null || true)"
    if [ "$status" = "healthy" ]; then
      return 0
    fi
    sleep 2
  done
  echo "$service did not become healthy" >&2
  compose ps >&2 || true
  compose logs --tail=120 "$service" >&2 || true
  exit 1
}

mysql_root() {
  compose exec -T mysql mariadb -uroot -pmochat_root "$@"
}

mysql_scalar() {
  local database="$1"
  local query="$2"
  compose exec -T mysql mariadb -umochat -pmochat_pass -N -B "$database" -e "$query" | tr -d '\r'
}

assert_port_free "$MYSQL_PORT"

compose up -d mysql
wait_service_healthy mysql

mysql_root <<'SQL'
DROP DATABASE IF EXISTS mochat_migrate_check;
DROP DATABASE IF EXISTS mochat_migrate_legacy;
DROP DATABASE IF EXISTS mochat_migrate_empty;
CREATE DATABASE mochat_migrate_check CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE DATABASE mochat_migrate_legacy CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE DATABASE mochat_migrate_empty CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
GRANT ALL PRIVILEGES ON mochat_migrate_check.* TO 'mochat'@'%';
GRANT ALL PRIVILEGES ON mochat_migrate_legacy.* TO 'mochat'@'%';
GRANT ALL PRIVILEGES ON mochat_migrate_empty.* TO 'mochat'@'%';
FLUSH PRIVILEGES;
